/**
 * Shapes of the demo data snapshots used by the live components. The JSON
 * files next to this module are GENERATED by the screenshot pipeline
 * (e2e/docs/data.setup.ts) from a fresh `arenile seed demo` and committed,
 * so `make docs-build` never needs a running server.
 *
 * Every value comes from the real server (map editor document, operational
 * day, pricing engine): the docs render it with the real web/shared
 * components and never recompute it. Random ids are replaced by stable keys
 * (spot labels, catalogue codes) so a regeneration only diffs real changes.
 */
import type { MapGeometry, SpotStatus } from '@arenile/shared/map';

/** Localised text as stored by Arenile ({ it: "...", en: "..." }). */
export type I18nText = Record<string, string>;

export interface DemoMapSnapshot {
  $comment: string;
  establishment: { name: string; slug: string };
  /** Operating day the statuses refer to (YYYY-MM-DD). */
  date: string;
  slot: 'FULL';
  /** Localised map name. */
  name: I18nText;
  /** Geometry for the shared BeachMap (labels of decorations in `decorationLabels`). */
  geometry: Omit<MapGeometry, 'name'>;
  decorationLabels: Record<string, I18nText>;
  /** Spot id -> status, computed with the operational mapping of the panel. */
  statuses: Record<string, SpotStatus>;
}

export type PriceStage = 'base' | 'modifier' | 'discount';

export interface DemoAppliedRule {
  rule: I18nText;
  stage: PriceStage;
  effect: string;
}

export interface DemoDay {
  date: string;
  slots: string;
  base: number;
  applied: DemoAppliedRule[];
  total: number;
}

export interface DemoScenario {
  pack: string;
  category: string;
  period: string;
  duration: string;
  starts_on: string;
  ends_on: string;
  formula: string;
  slots: string;
  /** Engine output (PriceBreakdown, trimmed to what the docs show), cents. */
  days: DemoDay[];
  extras_total: number;
  discounts: { source: string; amount: number }[];
  rounding: number;
  total: number;
  vat: { rate: string; taxable: number; tax: number }[];
  deposit_due: number;
}

export interface DemoPricingSnapshot {
  $comment: string;
  establishment: { name: string; slug: string };
  season: { name: string; opens_on: string; closes_on: string };
  currency: string;
  channel: string;
  engine_version: number;
  packs: { code: string; name: I18nText }[];
  categories: { code: string; zone: I18nText }[];
  periods: { code: string; name: I18nText; color?: string | null }[];
  durations: { code: string; days: number; formula: string; slots: string }[];
  scenarios: DemoScenario[];
}
